import{_ as o,l as c,o as a,c as d,v as i,p as t,x as s,d as r,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"sendfile 与 splice","description":"","frontmatter":{"title":"sendfile 与 splice","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sendfile-splice.md","filePath":"cs/sendfile-splice.md","lastUpdated":1789023840000}'),f={name:"cs/sendfile-splice.md"};function _(h,e,m,u,E,S){const l=c("Mermaid");return a(),d("div",null,[e[1]||(e[1]=i('<h1 id="sendfile-与-splice" tabindex="-1">sendfile 与 splice <a class="header-anchor" href="#sendfile-与-splice" aria-label="Permalink to &quot;sendfile 与 splice&quot;">​</a></h1><div class="epigraph"><p>sendfile 把文件页直接送进套接字发送队列；splice 用管道当中转，让两个 fd 在内核里接力，而不经过用户缓冲。</p><footer>—— 据 Linux sendfile(2)、splice(2)；Niels Provos 等对零拷贝服务器的实践讨论</footer></div><p><a href="/cs/posix-aio">上一课</a>仍假设数据有一份用户缓冲。<a href="/cs/page-cache">页缓存</a> 里已经有文件帧，静态 Web 还把它 <code>read</code> 进用户再 <code>write</code> 到套接字——两次拷贝。缺口是 <strong>sendfile/splice</strong>：内核内搬运。文件系统接口课序在此收口，下一课序进入块层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>read</code>+<code>write</code>：内核→用户→内核。sendfile：从文件 fd 的页缓存把页挂到 socket 的 sk_buff（或等价物），DMA 出网卡。splice：任意两个可拼接的 fd，经 pipe 缓冲。缺口：何时必须拷贝（用户不能 DMA 的页、加密、checksum 卸载失败）；与 <a href="/cs/direct-io">O_DIRECT</a> 文件组合的限制；<code>TCP_CORK</code>/<code>MSG_MORE</code> 如何攒包——网络细节点到为止，对象是 FS 与套接字的接头。</p><p><span class="marginnote"><code>copy_file_range</code> 是文件到文件的亲戚。本课不把 sk_buff 结构写完，那是网络栈第一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>静态文件：<code>open</code> 文件，<code>sendfile(out_sock, in_file, &amp;off, len)</code>。内核 <code>do_splice_to</code> 从 file 拉页，<code>do_splice_from</code> 推向 socket。若页需修改（如加 TLS 头），走一次拷贝。对照 mmap+write：仍可能拷；sendfile 意图是避免用户态触及。对照 FUSE：用户态 FS 的页可能无法零拷贝。</p>',8)),(a(),t(p,null,{default:s(()=>[n(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILE%5B%22%E6%96%87%E4%BB%B6%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%20--%3E%20SF%5B%22sendfile%2Fsplice%22%5D%0A%20%20SF%20--%3E%20SOCK%5B%22%E5%A5%97%E6%8E%A5%E5%AD%97%E5%8F%91%E9%80%81%22%5D%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E7%BC%93%E5%86%B2%22%5D%20-.-%3E%7C%22%E4%B8%8D%E7%BB%8F%E8%BF%87%22%7C%20SF%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>零拷贝把服务器 CPU 从 memcpy 里解放，使瓶颈回到设备与协议栈。它不替代 <a href="/cs/fsync">fsync</a>，也不保证 <code>O_DIRECT</code> 源。不要把「零拷贝」写成绝对：统计、cgroup、安全钩仍可能碰数据。与预读：sendfile 顺序发文件会触发同一套预读，这是性能上的朋友。</p><p>文件系统进阶到此：布局到接口都已接到「字节如何离开内核」。下一单元从块层调度器开始，那些页最终要排成对设备的请求。</p><p>实现上：TLS 内核卸载或需要修改字节时，零拷贝会降级。splice 进管道受管道容量限制，大文件要循环。copy_file_range 可在 FS 内克隆块（reflink），那是另一条减拷贝。 读法上只引用<a href="/cs/posix-aio">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>sendfile 与 splice</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 eBPF 改包、TLS 内核卸载的全部套件。不保证每张网卡的 scatter-gather 成功。存储栈第一课：请求在块层如何排队——mq-deadline 与 BFQ。</p><p>版本字段会变，课序钉的是机制对象「sendfile 与 splice」，不是某一主线内核的结构体名。 后课默认：文件页可不进用户空间就送走。块层调度器如何排这些请求，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>sendfile/splice 在内核把文件页交给管道或套接字。</li><li>失败回退到拷贝；不替代持久语义。</li><li>块层调度是下一单元。</li><li>出处：Linux <code>sendfile(2)</code>、<code>splice(2)</code>；<em>OSTEP</em> 对 I/O 路径；Stevens 对 sendfile 的背景。</li></ul>',11))])}const k=o(f,[["render",_]]);export{B as __pageData,k as default};
